const std = @import("std"); const mem2 = std.mem; const obje = @import("pa-pdfz-obje.zig"); const cmap = @import("pa-pdfz-cmap.zig");
const CF = .{ .pagz = 3000, .textz = 8 << 20, .depz = 24, .gapz = -200.0, .opsz = 8 };
pub const Rslt = struct { text: []const u8, pag2: u32, ocrz: bool };
const Font = struct { cmpz: ?cmap.Cmap = null, cswz: u8 = 1 };
const FilzName = struct { name: []const u8, font: *Font };
const Ctxz = struct { docz: *obje.Docz, aren: std.mem.Allocator, outp: std.ArrayList(u8) = .empty, pag2: u32 = 0, fcac: std.AutoHashMapUnmanaged(u32, *Font) = .empty };
const Tokz = struct { numz: f64 = 0, strz: []const u8 = "", kind: u8 = 0 };
const Stzz = struct { yyyz: f64 = 0, las5: f64 = 0, lead: f64 = 12, have: bool = false, gap2: bool = false, font: ?*Font = null };
fn fontLoad(ctx2: *Ctxz, num2: u32) !*Font { if (ctx2.fcac.get(num2)) |hitz| return hitz; const fntz = try ctx2.aren.create(Font); fntz.* = .{}; try ctx2.fcac.put(ctx2.aren, num2, fntz); const body = ctx2.docz.objs.get(num2) orelse return fntz; const pszz = try obje.dictPair(ctx2.aren, body); if (obje.pairGetz(pszz, "Subtype")) |sub| { if (mem2.find(u8, sub, "Type0") != null) fntz.cswz = 2; } if (obje.pairGetz(pszz, "ToUnicode")) |touz| { if (obje.refzOfzz(touz)) |tnum| { if (ctx2.docz.objs.get(tnum)) |tbod| { if (obje.streOfzz(ctx2.docz, tbod)) |decz| { if (cmap.cmapPars(ctx2.aren, decz)) |cmpz| { fntz.cmpz = cmpz; if (cmpz.cswz != 0) fntz.cswz = cmpz.cswz; } else |_| {} } else |_| {} } } } return fntz; }
fn reso(ctx2: *Ctxz, val2: []const u8) []const u8 { if (obje.refzOfzz(val2)) |num2| return ctx2.docz.objs.get(num2) orelse ""; return val2; }
fn fontOfzz(ctx2: *Ctxz, resv: ?[]const u8, list: *std.ArrayList(FilzName)) !void { const rslt = reso(ctx2, resv orelse return); const rpsz = try obje.dictPair(ctx2.aren, rslt); const fdvz = reso(ctx2, obje.pairGetz(rpsz, "Font") orelse return); const fpsz = try obje.dictPair(ctx2.aren, fdvz); for (fpsz) |pair| { const num2 = obje.refzOfzz(pair.val2) orelse continue; try list.append(ctx2.aren, .{ .name = pair.key2, .font = try fontLoad(ctx2, num2) }); } }
fn emit(ctx2: *Ctxz, stzz: *Stzz, byts: []const u8) !void { if (ctx2.outp.items.len > CF.textz) return error.TooMany; if (stzz.have and @abs(stzz.yyyz - stzz.las5) > 0.5) { try ctx2.outp.append(ctx2.aren, '\n'); } else if (stzz.gap2 and ctx2.outp.items.len > 0) { const lstz = ctx2.outp.items[ctx2.outp.items.len - 1]; if (lstz != ' ' and lstz != '\n') try ctx2.outp.append(ctx2.aren, ' '); } stzz.gap2 = false; stzz.have = true; stzz.las5 = stzz.yyyz; if (stzz.font) |fntz| { if (fntz.cmpz) |cmpz| { _ = try cmap.cmapDeco(cmpz, ctx2.aren, byts, &ctx2.outp, fntz.cswz); return; } if (fntz.cswz == 2) return; } for (byts) |chr2| { if (chr2 == '\n' or chr2 == '\t' or (chr2 >= 0x20 and chr2 != 0x7f)) { var buf4: [4]u8 = undefined; const lenz = std.unicode.utf8Encode(chr2, &buf4) catch continue; try ctx2.outp.appendSlice(ctx2.aren, buf4[0..lenz]); } } }
fn litzStrz(aren: std.mem.Allocator, srcz: []const u8, from: usize, endp: *usize) ![]const u8 { var outp: std.ArrayList(u8) = .empty; var kixz = from + 1; var depz: usize = 1; while (kixz < srcz.len) : (kixz += 1) { const chr2 = srcz[kixz]; if (chr2 == '\\' and kixz + 1 < srcz.len) { kixz += 1; const escz = srcz[kixz]; switch (escz) { 'n' => try outp.append(aren, '\n'), 'r' => try outp.append(aren, '\r'), 't' => try outp.append(aren, '\t'), 'b' => try outp.append(aren, 8), 'f' => try outp.append(aren, 12), '0'...'7' => { var val2: u32 = escz - '0'; var con2: usize = 1; while (con2 < 3 and kixz + 1 < srcz.len and srcz[kixz + 1] >= '0' and srcz[kixz + 1] <= '7') : (con2 += 1) { kixz += 1; val2 = val2 * 8 + (srcz[kixz] - '0'); } try outp.append(aren, @truncate(val2)); }, '\n' => {}, '\r' => { if (kixz + 1 < srcz.len and srcz[kixz + 1] == '\n') kixz += 1; }, else => try outp.append(aren, escz) } } else if (chr2 == '(') { depz += 1; try outp.append(aren, chr2); } else if (chr2 == ')') { depz -= 1; if (depz == 0) { endp.* = kixz + 1; return outp.toOwnedSlice(aren); } try outp.append(aren, chr2); } else try outp.append(aren, chr2); } endp.* = srcz.len; return outp.toOwnedSlice(aren); }
fn hexzStrz(aren: std.mem.Allocator, srcz: []const u8, from: usize, endp: *usize) ![]const u8 { const cloz = mem2.findScalarPos(u8, srcz, from, '>') orelse srcz.len; endp.* = @min(cloz + 1, srcz.len); var outp: std.ArrayList(u8) = .empty; var hizz: ?u8 = null; for (srcz[from + 1 .. cloz]) |chr2| { const digz = std.fmt.charToDigit(chr2, 16) catch continue; if (hizz) |hvzz| { try outp.append(aren, (hvzz << 4) | digz); hizz = null; } else hizz = digz; } if (hizz) |hvzz| try outp.append(aren, hvzz << 4); return outp.toOwnedSlice(aren); }
fn numbOfzz(tokz: ?Tokz) f64 { if (tokz) |tkzz| return tkzz.numz; return 0; }
fn contRunz(ctx2: *Ctxz, data: []const u8, fon2: []const FilzName) !void { var stzz: Stzz = .{}; var stk2: [CF.opsz]Tokz = undefined; var con2: usize = 0; var kixz: usize = 0; while (kixz < data.len) { kixz = obje.skipWszz(data, kixz); if (kixz >= data.len) break; const chr2 = data[kixz]; var tokz: ?Tokz = null; if (chr2 == '(') { var endp: usize = 0; tokz = .{ .strz = try litzStrz(ctx2.aren, data, kixz, &endp), .kind = 's' }; kixz = endp; } else if (chr2 == '<' and kixz + 1 < data.len and data[kixz + 1] != '<') { var endp: usize = 0; tokz = .{ .strz = try hexzStrz(ctx2.aren, data, kixz, &endp), .kind = 's' }; kixz = endp; } else if (chr2 == '<' or chr2 == '>') { kixz = obje.valuEndz(data, kixz); if (chr2 == '>') kixz = @max(kixz, 1); } else if (chr2 == '[') { const aend = obje.valuEndz(data, kixz); var lis2: std.ArrayList(u8) = .empty; var jixz = kixz + 1; var sstz = Stzz{ .font = stzz.font, .yyyz = stzz.yyyz, .las5 = stzz.yyyz, .have = false }; const mark = ctx2.outp.items.len; while (jixz < aend - 1) { jixz = obje.skipWszz(data, jixz); if (jixz >= aend - 1) break; const cczz = data[jixz]; if (cczz == '(') { var endp: usize = 0; const sval = try litzStrz(ctx2.aren, data, jixz, &endp); try emitList(ctx2, &stzz, sval); jixz = endp; } else if (cczz == '<') { var endp: usize = 0; const sval = try hexzStrz(ctx2.aren, data, jixz, &endp); try emitList(ctx2, &stzz, sval); jixz = endp; } else { var jenz = jixz; while (jenz < aend and !obje.iszzWszz(data[jenz]) and !obje.iszzDelz(data[jenz])) jenz += 1; if (jenz == jixz) jenz = jixz + 1; const nval = std.fmt.parseFloat(f64, data[jixz..jenz]) catch 0; if (nval < CF.gapz) stzz.gap2 = true; jixz = jenz; } } _ = &lis2; _ = &sstz; _ = mark; kixz = aend; tokz = .{ .kind = 'a' }; } else if (chr2 == '/') { const nenz = obje.valuEndz(data, kixz); tokz = .{ .strz = data[kixz + 1 .. nenz], .kind = 'n' }; kixz = nenz; } else if (std.ascii.isDigit(chr2) or chr2 == '-' or chr2 == '+' or chr2 == '.') { var nenz = kixz + 1; while (nenz < data.len and (std.ascii.isDigit(data[nenz]) or data[nenz] == '.' or data[nenz] == '-')) nenz += 1; tokz = .{ .numz = std.fmt.parseFloat(f64, data[kixz..nenz]) catch 0, .kind = 'd' }; kixz = nenz; } else if (chr2 == ']' or chr2 == '{' or chr2 == '}' or chr2 == ')') { kixz += 1; continue; }
if (tokz) |tkzz| { if (con2 == stk2.len) { mem2.copyForwards(Tokz, stk2[0 .. stk2.len - 1], stk2[1..]); con2 -= 1; } stk2[con2] = tkzz; con2 += 1; continue; }
var oenz = kixz; while (oenz < data.len and !obje.iszzWszz(data[oenz]) and !obje.iszzDelz(data[oenz])) oenz += 1; if (oenz == kixz) { kixz += 1; continue; } const oprz = data[kixz..oenz]; kixz = oenz; const topz: ?Tokz = if (con2 > 0) stk2[con2 - 1] else null; const secz: ?Tokz = if (con2 > 1) stk2[con2 - 2] else null;
if (mem2.eql(u8, oprz, "BT")) { stzz.yyyz = 0; } else if (mem2.eql(u8, oprz, "Tf")) { if (secz) |nmzz| { stzz.font = null; for (fon2) |fn_| { if (mem2.eql(u8, fn_.name, nmzz.strz)) { stzz.font = fn_.font; break; } } } } else if (mem2.eql(u8, oprz, "Tj")) { if (topz) |tkzz| try emit(ctx2, &stzz, tkzz.strz); } else if (mem2.eql(u8, oprz, "'") or mem2.eql(u8, oprz, "\"")) { stzz.yyyz -= stzz.lead; if (topz) |tkzz| try emit(ctx2, &stzz, tkzz.strz); } else if (mem2.eql(u8, oprz, "Td") or mem2.eql(u8, oprz, "TD")) { stzz.yyyz += numbOfzz(topz); if (mem2.eql(u8, oprz, "TD")) stzz.lead = -numbOfzz(topz); if (numbOfzz(secz) != 0) stzz.gap2 = true; } else if (mem2.eql(u8, oprz, "Tm")) { stzz.yyyz = numbOfzz(topz); stzz.gap2 = true; } else if (mem2.eql(u8, oprz, "T*")) { stzz.yyyz -= stzz.lead; } else if (mem2.eql(u8, oprz, "TL")) { stzz.lead = numbOfzz(topz); } else if (mem2.eql(u8, oprz, "ET")) { stzz.gap2 = true; } else if (mem2.eql(u8, oprz, "BI")) { const eixz = mem2.findPos(u8, data, kixz, "EI") orelse data.len; kixz = @min(eixz + 2, data.len); }
con2 = 0; } }
fn emitList(ctx2: *Ctxz, stzz: *Stzz, byts: []const u8) !void { try emit(ctx2, stzz, byts); }
fn pageDozz(ctx2: *Ctxz, body: []const u8, inhr: ?[]const u8) !void { const pszz = try obje.dictPair(ctx2.aren, body); const resv = obje.pairGetz(pszz, "Resources") orelse inhr; var fon2: std.ArrayList(FilzName) = .empty; try fontOfzz(ctx2, resv, &fon2); const cvzz = obje.pairGetz(pszz, "Contents") orelse return; var refs: std.ArrayList(u32) = .empty; const cbdz = reso(ctx2, cvzz); if (obje.refzOfzz(cvzz)) |num2| { if (mem2.startsWith(u8, mem2.trimStart(u8, cbdz, " \t\r\n"), "[")) { var jixz: usize = 0; while (jixz < cbdz.len) { const nxzz = obje.skipWszz(cbdz, jixz); if (nxzz >= cbdz.len) break; const vezz = obje.valuEndz(cbdz, nxzz); if (obje.refzOfzz(cbdz[nxzz..vezz])) |rnzz| try refs.append(ctx2.aren, rnzz); jixz = @max(vezz, nxzz + 1); } } else try refs.append(ctx2.aren, num2); } else { var jixz: usize = 0; while (jixz < cvzz.len) { const nxzz = obje.skipWszz(cvzz, jixz); if (nxzz >= cvzz.len) break; const vezz = obje.valuEndz(cvzz, nxzz); if (obje.refzOfzz(cvzz[nxzz..vezz])) |rnzz| try refs.append(ctx2.aren, rnzz); jixz = @max(vezz, nxzz + 1); } } var all: std.ArrayList(u8) = .empty; for (refs.items) |rnzz| { const sbzz = ctx2.docz.objs.get(rnzz) orelse continue; const decz = obje.streOfzz(ctx2.docz, sbzz) catch continue; try all.appendSlice(ctx2.aren, decz); try all.append(ctx2.aren, '\n'); } const before = ctx2.outp.items.len; try contRunz(ctx2, all.items, fon2.items); if (ctx2.outp.items.len > before) try ctx2.outp.appendSlice(ctx2.aren, "\n\n"); ctx2.pag2 += 1; }
fn treeWalk(ctx2: *Ctxz, num2: u32, inhr: ?[]const u8, depz: usize, seen: *std.AutoHashMapUnmanaged(u32, void)) !void { if (depz > CF.depz or ctx2.pag2 >= CF.pagz or seen.contains(num2)) return; try seen.put(ctx2.aren, num2, {}); const body = ctx2.docz.objs.get(num2) orelse return; const pszz = try obje.dictPair(ctx2.aren, body); const kids = obje.pairGetz(pszz, "Kids"); const resv = obje.pairGetz(pszz, "Resources") orelse inhr; if (kids) |kdsz| { var jixz: usize = 0; while (jixz < kdsz.len) { const nxzz = obje.skipWszz(kdsz, jixz + (if (jixz == 0) @as(usize, 1) else 0)); if (nxzz >= kdsz.len) break; const vezz = obje.valuEndz(kdsz, nxzz); if (obje.refzOfzz(kdsz[nxzz..vezz])) |rnzz| try treeWalk(ctx2, rnzz, resv, depz + 1, seen); jixz = @max(vezz, nxzz + 1); } return; } try pageDozz(ctx2, body, inhr); }
fn rootOfzz(data: []const u8) ?u32 { var kixz: usize = 0; var best: ?u32 = null; while (mem2.findPos(u8, data, kixz, "/Root")) |hitz| { kixz = hitz + 5; const nxzz = obje.skipWszz(data, kixz); const vezz = obje.valuEndz(data, nxzz); if (obje.refzOfzz(data[nxzz..vezz])) |rnzz| best = rnzz; } return best; }
pub fn pdfzText(tmpz: std.mem.Allocator, aren: std.mem.Allocator, data: []const u8) !Rslt { var docz = try obje.doczOpen(aren, tmpz, data); var ctx2: Ctxz = .{ .docz = &docz, .aren = aren }; var seen: std.AutoHashMapUnmanaged(u32, void) = .empty; if (rootOfzz(data)) |rnzz| { if (docz.objs.get(rnzz)) |catz| { const cpsz = try obje.dictPair(aren, catz); if (obje.pairGetz(cpsz, "Pages")) |pgvz| { if (obje.refzOfzz(pgvz)) |pnzz| treeWalk(&ctx2, pnzz, null, 0, &seen) catch |err3| { if (err3 == error.TooMany or err3 == error.OutOfMemory) return err3; }; } } } if (ctx2.pag2 == 0) { var nums: std.ArrayList(u32) = .empty; var iter = docz.objs.iterator(); while (iter.next()) |entr| { const bod2 = entr.value_ptr.*; const pszz = obje.dictPair(aren, bod2) catch continue; const typ2 = obje.pairGetz(pszz, "Type") orelse continue; if (mem2.eql(u8, typ2, "/Page")) try nums.append(aren, entr.key_ptr.*); } mem2.sort(u32, nums.items, {}, std.sort.asc(u32)); for (nums.items) |nnzz| { if (ctx2.pag2 >= CF.pagz) break; pageDozz(&ctx2, docz.objs.get(nnzz).?, null) catch |err3| { if (err3 == error.TooMany or err3 == error.OutOfMemory) return err3; }; } } const text = mem2.trim(u8, ctx2.outp.items, " \t\r\n"); return .{ .text = text, .pag2 = ctx2.pag2, .ocrz = text.len == 0 or (ctx2.pag2 >= 3 and text.len < ctx2.pag2 * 4) }; }
